{"code":"import ijson

def _num(v):
    if v is None:
        return None
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        s = v.strip().replace("$", "").replace(",", "").replace("%", "")
        if not s:
            return None
        try:
            return float(s)
        except Exception:
            return None
    return None

def _str(v):
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    if isinstance(v, (list, tuple)):
        parts = [_str(x) for x in v]
        parts = [p for p in parts if p]
        if not parts:
            return None
        # setting list: if single return it, if multiple join with /
        return parts[0] if len(parts) == 1 else "/".join(parts)
    return str(v)

def _get(d, *keys):
    if not isinstance(d, dict):
        return None
    # case-insensitive lookup
    lower = {}
    for k, v in d.items():
        lower[str(k).lower()] = v
    for key in keys:
        if key.lower() in lower:
            return lower[key.lower()]
    return None

def _codes(item):
    codes = []
    ci = _get(item, "code_information", "codes", "billing_codes")
    if isinstance(ci, list):
        for e in ci:
            if isinstance(e, dict):
                code = _get(e, "code", "billing_code")
                typ = _get(e, "type", "code_type", "type_name")
                if code is not None and str(code).strip():
                    codes.append({"code": str(code).strip(), "type": _str(typ) or ""})
            elif e is not None and str(e).strip():
                codes.append({"code": str(e).strip(), "type": ""})
    elif isinstance(ci, dict):
        code = _get(ci, "code")
        typ = _get(ci, "type")
        if code:
            codes.append({"code": str(code).strip(), "type": _str(typ) or ""})
    # fallback single code/type on item
    if not codes:
        code = _get(item, "code", "billing_code")
        typ = _get(item, "type", "code_type")
        if code is not None and str(code).strip():
            codes.append({"code": str(code).strip(), "type": _str(typ) or ""})
    # also codes inside standard_charges? check later if empty - handled by caller merging?
    return codes

def parse(fp):
    try:
        items = ijson.items(fp, "standard_charge_information.item")
        for item in items:
            try:
                if not isinstance(item, dict):
                    continue
                description = _str(_get(item, "description"))
                setting_raw = _get(item, "setting")
                setting = _str(setting_raw)
                if setting:
                    setting = setting.lower()
                modifiers_raw = _get(item, "modifiers", "modifier", "modifiers_description")
                # modifiers could be list of dicts/strings
                if isinstance(modifiers_raw, list):
                    parts = []
                    for m in modifiers_raw:
                        if isinstance(m, dict):
                            parts.append(_str(_get(m, "modifier", "modifiers", "code", "description")) or "")
                        else:
                            parts.append(_str(m) or "")
                    modifiers = ",".join([p for p in parts if p]) or None
                else:
                    modifiers = _str(modifiers_raw)
                codes = _codes(item)
                billing_class_item = _str(_get(item, "billing_class", "billingclass", "class"))

                charges = _get(item, "standard_charges", "standard_charge", "charges")
                if not isinstance(charges, list) or not charges:
                    charges = [item]  # treat item itself as charge container

                for sc in charges:
                    if not isinstance(sc, dict):
                        continue
                    # codes may be on sc
                    sc_codes = codes if codes else _codes(sc)
                    # If sc_codes differ and codes too? merge unique?
                    if not codes and sc_codes:
                        use_codes = sc_codes
                    else:
                        use_codes = codes
                    # also if sc has code_information, append
                    if sc is not item:
                        extra = _codes(sc)
                        if extra and extra not in use_codes:
                            # merge
                            seen = {(c["code"], c["type"]) for c in use_codes}
                            for c in extra:
                                if (c["code"], c["type"]) not in seen:
                                    use_codes = list(use_codes) + [c]

                    gross = _num(_get(sc, "gross_charge", "gross", "standard_charge|gross", "standard_charge_gross"))
                    cash = _num(_get(sc, "discounted_cash", "discounted_cash_price", "cash", "standard_charge|discounted_cash"))
                    mn = _num(_get(sc, "minimum", "min", "minimum_charge", "standard_charge|minimum"))
                    mx = _num(_get(sc, "maximum", "max", "maximum_charge", "standard_charge|maximum"))
                    methodology = _str(_get(sc, "methodology", "method"))
                    billing_class = _str(_get(sc, "billing_class")) or billing_class_item
                    est_sc = _num(_get(sc, "estimated_amount", "median_amount", "estimated_charge"))
                    setting_sc = _str(_get(sc, "setting")) or setting
                    if setting_sc:
                        setting_sc = setting_sc.lower()
                    desc_sc = _str(_get(sc, "description")) or description

                    payers = _get(sc, "payers_information", "payer_information", "payers", "standard_charge_information")
                    # payers_information in some schemas is list; ensure list
                    if isinstance(payers, dict):
                        payers = [payers]
                    if not isinstance(payers, list) or not payers:
                        yield {
                            "description": desc_sc,
                            "codes": list(use_codes),
                            "setting": setting_sc,
                            "billing_class": billing_class,
                            "modifiers": modifiers,
                            "gross": gross,
                            "cash": cash,
                            "min": mn,
                            "max": mx,
                            "payer_name": None,
                            "plan_name": None,
                            "negotiated_dollar": None,
                            "negotiated_percentage": None,
                            "negotiated_algorithm": None,
                            "estimated_amount": est_sc,
                            "methodology": methodology,
