                            est = _num(_get(p, "estimated_amount", "median_amount", "estimated_charge"))
                            if est is None:
                                est = est_sc
                            # payer-level gross/cash/min/max fallback
                            g = gross if gross is not None else _num(_get(p, "gross_charge", "gross"))
                            csh = cash if cash is not None else _num(_get(p, "discounted_cash", "cash"))
                            mi = mn if mn is not None else _num(_get(p, "minimum", "min"))
                            ma = mx if mx is not None else _num(_get(p, "maximum", "max"))
                            meth = methodology or _str(_get(p, "methodology"))
                            yield {
